"""Maximum XOR With an Element From Array — offline queries over a bitwise trie.

Sorting the numbers and the queries by their limit means each number is inserted
once, and every query only sees the elements it is allowed to use.

Time: O((n + q) * 32)   Space: O(n * 32)
"""
from typing import List


class Solution:
    def maximizeXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        nums.sort()
        root = {}

        def insert(value: int) -> None:
            node = root
            for bit in range(29, -1, -1):
                b = (value >> bit) & 1
                node = node.setdefault(b, {})

        def best_xor(value: int) -> int:
            node, out = root, 0
            for bit in range(29, -1, -1):
                b = (value >> bit) & 1
                want = 1 - b
                if want in node:
                    out |= 1 << bit
                    node = node[want]
                else:
                    node = node[b]
            return out

        out = [-1] * len(queries)
        i = 0
        for index, (x, limit) in sorted(enumerate(queries), key=lambda q: q[1][1]):
            while i < len(nums) and nums[i] <= limit:
                insert(nums[i])
                i += 1
            out[index] = best_xor(x) if i else -1
        return out
